// A1-5a ReFS read-only volume regression.
//
// Corpus: testdata/refs-golden/{cases.tsv,files.tsv,*.bin}, generated by an
// independent pure-Python oracle (Gen-ReFSGolden.py).  Every successful case
// exercises the full bootstrap chain VBR -> best-of-3 SUPB -> best-of-2 CHKP
// -> 13 root page references (Merkle digest) -> Container Table VLCN->PLCN
// -> Object Table / Parent-Child Table -> per-directory MSB+ B+-tree
// -> directory entries -> inline $DATA or 24-byte extents -> file bytes.
//
// The corpus is SYNTHETIC (published byte offsets, flattened golden $DATA
// sub-record layout).  Real Windows ReFS volumes are tracked as A1-5b.
//
// Zero GUI / zero device I/O / zero writes.

#include "../fs/refs/RefsVolume.h"

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

using namespace phoenix::refs;

static int g_fail = 0;
static int g_checks = 0;

#define CHECK(cond, what)                                                        \
    do {                                                                         \
        ++g_checks;                                                              \
        if (!(cond)) {                                                           \
            std::printf("FAIL line %d: %s\n", __LINE__, (what));                 \
            ++g_fail;                                                            \
        }                                                                        \
    } while (0)

static std::vector<std::string> SplitTabs(const std::string& line)
{
    std::vector<std::string> out;
    std::string cur;
    std::istringstream is(line);
    while (std::getline(is, cur, '\t')) out.push_back(cur);
    return out;
}

static std::vector<std::string> ReadLines(const std::string& path)
{
    std::vector<std::string> out;
    std::ifstream f(path);
    std::string line;
    while (std::getline(f, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (!line.empty() && line[0] != '#') out.push_back(line);
    }
    return out;
}

static std::vector<uint8_t> ReadBinary(const std::string& path)
{
    std::ifstream f(path, std::ios::binary);
    return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),
                                std::istreambuf_iterator<char>());
}

static std::string Hex(const uint8_t* p, size_t n)
{
    static const char* d = "0123456789abcdef";
    std::string s;
    s.reserve(n * 2);
    for (size_t i = 0; i < n; ++i) {
        s += d[p[i] >> 4];
        s += d[p[i] & 15];
    }
    return s;
}

static std::string FnvHex(const uint8_t* p, size_t n)
{
    char buf[24];
    std::snprintf(buf, sizeof(buf), "%016llx",
                  static_cast<unsigned long long>(Fnv1a64(p, n)));
    return buf;
}

static std::string GoldenDir()
{
    std::vector<std::string> candidates;
    const char* env = std::getenv("PHOENIX_REFS_GOLDEN");
    if (env && *env) candidates.emplace_back(std::string(env) + "/");
    candidates.emplace_back("testdata/refs-golden/");
    candidates.emplace_back("../testdata/refs-golden/");
    candidates.emplace_back("../../testdata/refs-golden/");
    candidates.emplace_back("../../../testdata/refs-golden/");
    candidates.emplace_back("../../../../testdata/refs-golden/");
    for (const std::string& d : candidates) {
        std::ifstream f(d + "cases.tsv");
        if (f.good()) return d;
    }
    return "testdata/refs-golden/";
}

struct ExpectFile
{
    std::string name, attrs, kind, sha, fnv, extents;
    uint64_t oid, size, allocated, create, modify, access;
    int isDir;
};

static std::string ExtentsString(const std::vector<RefsExtent>& ex)
{
    std::string s;
    for (size_t i = 0; i < ex.size(); ++i) {
        if (i) s += ';';
        s += std::to_string(ex[i].vcn) + ":" + std::to_string(ex[i].vlcn) +
             ":" + std::to_string(ex[i].length);
    }
    return s.empty() ? "-" : s;
}

static std::string Narrow(const std::wstring& w)
{
    std::string s;
    for (wchar_t c : w) s.push_back(static_cast<char>(c & 0xFF));
    return s;
}

int main()
{
    const std::string dir = GoldenDir();
    std::printf("RefsVolume golden dir: %s\n", dir.c_str());
    const auto caseLines = ReadLines(dir + "cases.tsv");
    const auto fileLines = ReadLines(dir + "files.tsv");
    CHECK(caseLines.size() == 15, "cases.tsv: header + 14 cases");
    CHECK(fileLines.size() == 55, "files.tsv: header + 54 live expectations");

    std::map<std::string, std::vector<ExpectFile>> expected;
    for (size_t i = 1; i < fileLines.size(); ++i) {
        const auto c = SplitTabs(fileLines[i]);
        if (c.size() < 14) { CHECK(false, "malformed files.tsv row"); continue; }
        ExpectFile e;
        e.name = c[2];
        e.oid = std::strtoull(c[1].c_str(), nullptr, 10);
        e.isDir = std::atoi(c[3].c_str());
        e.size = std::strtoull(c[4].c_str(), nullptr, 10);
        e.allocated = std::strtoull(c[5].c_str(), nullptr, 10);
        e.attrs = c[6];
        e.create = std::strtoull(c[7].c_str(), nullptr, 10);
        e.modify = std::strtoull(c[8].c_str(), nullptr, 10);
        e.access = std::strtoull(c[9].c_str(), nullptr, 10);
        e.kind = c[10];
        e.sha = c[11];
        e.fnv = c[12];
        e.extents = c[13];
        expected[c[0]].push_back(e);
    }

    int okCases = 0, negativeCases = 0, filesChecked = 0, contentChecked = 0;
    for (size_t i = 1; i < caseLines.size(); ++i) {
        const auto c = SplitTabs(caseLines[i]);
        if (c.size() < 13) { CHECK(false, "malformed cases.tsv row"); continue; }
        const std::string& name = c[0];
        const std::string& image = c[1];
        const std::string& wantStatus = c[2];
        const size_t wantFiles = static_cast<size_t>(std::strtoull(c[3].c_str(), nullptr, 10));
        FileRefsImage img(dir + image);
        CHECK(img.IsOpen(), (name + ": image readable").c_str());
        if (!img.IsOpen()) continue;
        RefsVolume vol;
        const RefsStatus st = vol.Open(img);
        CHECK(wantStatus == RefsStatusName(st),
              (name + ": Open() == " + wantStatus + ", got " +
               RefsStatusName(st) + " [" + vol.LastError() + "]").c_str());
        if (st != RefsStatus::Ok) { ++negativeCases; continue; }
        ++okCases;

        const RefsGeometry& g = vol.Info().geometry;
        CHECK(g.bytesPerSector == std::strtoul(c[4].c_str(), nullptr, 10),
              (name + ": bytesPerSector").c_str());
        CHECK(g.sectorsPerCluster == std::strtoul(c[5].c_str(), nullptr, 10),
              (name + ": sectorsPerCluster").c_str());
        CHECK(g.clusterSize == std::strtoull(c[6].c_str(), nullptr, 10),
              (name + ": clusterSize").c_str());
        CHECK(g.pageSize == std::strtoull(c[7].c_str(), nullptr, 10),
              (name + ": pageSize").c_str());
        CHECK(g.clustersPerContainer == std::strtoull(c[8].c_str(), nullptr, 10),
              (name + ": clustersPerContainer").c_str());
        CHECK(vol.Info().indirectRootList == (c[9] == "indirect"),
              (name + ": root list mode").c_str());
        CHECK(vol.Info().checksumType == (c[10] == "crc64" ? 2u : 4u),
              (name + ": checksum type").c_str());
        CHECK(g.minorVersion == std::strtoul(c[11].c_str(), nullptr, 10),
              (name + ": minor version").c_str());
        CHECK(vol.Info().rootCount == 13, (name + ": 13 roots").c_str());
        CHECK(vol.Info().containerCount >= 1, (name + ": container map").c_str());
        CHECK(vol.Info().objectCount == 2, (name + ": two directory objects").c_str());

        // Parent-Child Table must expose root -> subdirectory.
        bool linkFound = false;
        for (const auto& p : vol.ParentChildLinks())
            if (p.first == 0x600ull && p.second == 0x700ull) linkFound = true;
        CHECK(linkFound, (name + ": parent-child link 0x600 -> 0x700").c_str());

        auto root = vol.ListDirectory(0x600);
        auto sub = vol.ListDirectory(0x700);
        CHECK(vol.LastStatus() == RefsStatus::Ok, (name + ": ListDirectory Ok").c_str());
        CHECK(root.size() == 5, (name + ": root has 5 entries").c_str());
        CHECK(sub.size() == 1, (name + ": subdir has 1 entry").c_str());
        CHECK(root.size() + sub.size() == wantFiles,
              (name + ": total file count").c_str());

        const auto& exp = expected[name];
        CHECK(exp.size() == wantFiles, (name + ": expectation row count").c_str());
        for (const auto& e : exp) {
            const auto& list = (e.oid == 0x600ull) ? root : sub;
            const RefsDirEntry* found = nullptr;
            for (const auto& item : list)
                if (Narrow(item.name) == e.name) { found = &item; break; }
            CHECK(found != nullptr, (name + "/" + e.name + ": discovered").c_str());
            if (!found) continue;
            ++filesChecked;
            CHECK(found->parentObjectId == e.oid, (name + "/" + e.name + ": parent OID").c_str());
            CHECK(static_cast<int>(found->isDirectory) == e.isDir,
                  (name + "/" + e.name + ": directory flag").c_str());
            CHECK(found->size == e.size, (name + "/" + e.name + ": size").c_str());
            CHECK(found->allocated == e.allocated,
                  (name + "/" + e.name + ": allocated").c_str());
            CHECK(found->createTime == e.create, (name + "/" + e.name + ": createTime").c_str());
            CHECK(found->modifyTime == e.modify, (name + "/" + e.name + ": modifyTime").c_str());
            CHECK(found->accessTime == e.access, (name + "/" + e.name + ": accessTime").c_str());
            char attrBuf[16];
            std::snprintf(attrBuf, sizeof(attrBuf), "0x%08x", found->attributes);
            CHECK(attrBuf == e.attrs, (name + "/" + e.name + ": attributes").c_str());
            const std::string gotKind = found->dataInline ? "inline" :
                                        (found->dataAvailable ? "extent" : "none");
            CHECK(gotKind == e.kind, (name + "/" + e.name + ": data kind").c_str());
            CHECK(ExtentsString(found->extents) == e.extents,
                  (name + "/" + e.name + ": extents").c_str());

            if (e.kind == "none") {
                size_t got = 99;
                uint8_t one = 0;
                CHECK(!vol.ReadFile(*found, 0, &one, 1, &got),
                      (name + "/" + e.name + ": no data -> refuses read").c_str());
                CHECK(vol.LastStatus() == RefsStatus::DataUnavailable,
                      (name + "/" + e.name + ": DataUnavailable").c_str());
                continue;
            }
            std::vector<uint8_t> content(static_cast<size_t>(e.size));
            size_t got = 0;
            CHECK(vol.ReadFile(*found, 0, content.data(), content.size(), &got),
                  (name + "/" + e.name + ": full read").c_str());
            CHECK(got == e.size, (name + "/" + e.name + ": full read length").c_str());
            CHECK(Hex(Sha256Of(content.data(), content.size()).data(), 32) == e.sha,
                  (name + "/" + e.name + ": content SHA-256").c_str());
            CHECK(FnvHex(content.data(), content.size()) == e.fnv,
                  (name + "/" + e.name + ": content FNV-1a").c_str());
            ++contentChecked;

            // Windowed read crossing an extent boundary (fragmented files).
            if (e.kind == "extent" && e.size > g.clusterSize * 2) {
                const uint64_t start = g.clusterSize * 2 - 17;
                const size_t length = 64;
                std::vector<uint8_t> window(length);
                size_t wgot = 0;
                CHECK(vol.ReadFile(*found, start, window.data(), length, &wgot),
                      (name + "/" + e.name + ": windowed cross-extent read").c_str());
                CHECK(wgot == length, (name + "/" + e.name + ": window length").c_str());
                CHECK(std::memcmp(window.data(), content.data() + start, length) == 0,
                      (name + "/" + e.name + ": window matches full content").c_str());
            }
            // Reading past EOF yields zero bytes, never fabricated content.
            {
                uint8_t buf[8] = {};
                size_t past = 99;
                CHECK(vol.ReadFile(*found, e.size + 16, buf, sizeof(buf), &past),
                      (name + "/" + e.name + ": past EOF is benign").c_str());
                CHECK(past == 0, (name + "/" + e.name + ": past EOF returns 0 bytes").c_str());
            }
        }

        // Unknown OID must not silently resolve to the root directory.
        {
            auto missing = vol.ListDirectory(0x9999);
            CHECK(missing.empty(), (name + ": unknown OID -> empty").c_str());
            CHECK(vol.LastStatus() == RefsStatus::ObjectNotFound,
                  (name + ": unknown OID -> ObjectNotFound").c_str());
        }
    }

    CHECK(okCases == 9, "9 positive volumes verified");
    CHECK(negativeCases == 5, "5 negative volumes correctly refused");
    CHECK(filesChecked == 54, "54 live file expectations compared");
    CHECK(contentChecked == 45, "45 live file contents reconstructed");

    // ---- Read-only guarantee + in-memory tamper detection -----------------
    {
        const std::string base = dir + "refs_v314_crc64_basic.bin";
        std::vector<uint8_t> data = ReadBinary(base);
        const std::vector<uint8_t> pristine = data;
        CHECK(data.size() == 8u * 1024u * 1024u, "basic image size");
        {
            MemoryRefsImage img(data);
            RefsVolume vol;
            CHECK(vol.Open(img) == RefsStatus::Ok, "in-memory image opens");
        }
        CHECK(data == pristine, "parser never writes to its source buffer");

        // A flipped VBR byte invalidates the ROR1+ADD self-checksum.
        {
            auto mutated = data;
            mutated[0x40] ^= 0x01;
            MemoryRefsImage img(mutated);
            RefsVolume vol;
            CHECK(vol.Open(img) == RefsStatus::BadVbrChecksum,
                  "tampered VBR -> BadVbrChecksum");
        }
        // A flipped metadata page byte breaks the parent's Merkle digest.
        {
            auto mutated = data;
            const uint64_t off = 352ull * 4096ull + 0x100ull;  // object-table page
            mutated[static_cast<size_t>(off)] ^= 0x80;
            MemoryRefsImage img(mutated);
            RefsVolume vol;
            const RefsStatus s = vol.Open(img);
            CHECK(s != RefsStatus::Ok, "tampered MSB+ page is refused");
            CHECK(s == RefsStatus::ChecksumMismatch ||
                  s == RefsStatus::BadPageSignature ||
                  s == RefsStatus::BadVolumeSignature,
                  "tampered MSB+ page -> integrity error");
        }
        // Corrupting the primary SUPB still allows backup recovery.
        {
            auto mutated = data;
            const uint64_t off = 30ull * 4096ull + 0xD0ull + 0x28ull;
            mutated[static_cast<size_t>(off)] ^= 0x01;
            MemoryRefsImage img(mutated);
            RefsVolume vol;
            CHECK(vol.Open(img) == RefsStatus::Ok,
                  "primary SUPB damage -> backup SUPB used");
            CHECK(vol.Info().superblockLcn != 30,
                  "backup SUPB actually selected");
        }
        // Container-table page: nh=0x78, row at +0x28, value at row+0x20,
        // physical start at value[len-16]=value+0x90 => page+0x150.
        // Roots #7/#8 are a failover pair: damaging one must fall back to the
        // duplicate and still produce identical file bytes; damaging both must
        // be refused rather than silently yielding zero-filled "recovered" data.
        const size_t ctOff    = static_cast<size_t>(100ull * 4096ull + 0x150ull);
        const size_t ctDupOff = static_cast<size_t>(108ull * 4096ull + 0x150ull);
        {
            auto mutated = data;
            mutated[ctOff] ^= 0x40;
            MemoryRefsImage img(mutated);
            RefsVolume vol;
            CHECK(vol.Open(img) == RefsStatus::Ok,
                  "one damaged Container-Table copy -> duplicate used");
            bool contentOk = false;
            for (const auto& e : vol.ListDirectory(0x600)) {
                if (Narrow(e.name) != "readme.txt" || !e.dataAvailable) continue;
                std::vector<uint8_t> buf(static_cast<size_t>(e.size));
                size_t got = 0;
                if (vol.ReadFile(e, 0, buf.data(), buf.size(), &got) &&
                    FnvHex(buf.data(), got) ==
                        expected["refs_v314_crc64_basic"][0].fnv)
                    contentOk = true;
            }
            CHECK(contentOk, "failover still reconstructs identical file bytes");
        }
        {
            auto mutated = data;
            mutated[ctOff] ^= 0x40;
            mutated[ctDupOff] ^= 0x40;
            MemoryRefsImage img(mutated);
            RefsVolume vol;
            CHECK(vol.Open(img) != RefsStatus::Ok,
                  "both Container-Table copies damaged -> volume refused");
        }
    }

    std::printf("RefsVolume: %d checks, %d failure(s), %d ok cases, "
                "%d refused cases, %d files, %d contents\n",
                g_checks, g_fail, okCases, negativeCases, filesChecked, contentChecked);
    if (g_fail != 0)
        std::printf("  corpus missing? run: python testdata/tools/Gen-ReFSGolden.py\n");
    return g_fail == 0 ? 0 : 1;
}
